INSERT INTO services (id, name, category, description, duration_min, price, image) VALUES (1, 'Limpeza de Pele Profunda', 'Facial', 'Higienização profunda com extração delicada, alta frequência e máscara calmante personalizada para renovar a luminosidade da pele.', 60, 180, '/assets/img/svc-limpeza.svg');
INSERT INTO services (id, name, category, description, duration_min, price, image) VALUES (2, 'Peeling de Diamante', 'Facial', 'Microdermoabrasão suave que promove renovação celular, uniformiza a textura cutânea e atenua poros dilatados e linhas finas.', 60, 220, '/assets/img/svc-peeling.svg');
INSERT INTO services (id, name, category, description, duration_min, price, image) VALUES (3, 'Harmonização Facial', 'Injetáveis', 'Protocolo personalizado com preenchedores e bioestimuladores para realçar contornos faciais com equilíbrio, simetria e naturalidade.', 90, 1850, '/assets/img/svc-harmonizacao.svg');
INSERT INTO services (id, name, category, description, duration_min, price, image) VALUES (4, 'Toxina Botulínica', 'Injetáveis', 'Aplicação precisa para suavizar linhas de expressão e prevenir rugas dinâmicas, preservando a expressão natural do rosto.', 30, 1100, '/assets/img/svc-botox.svg');
INSERT INTO services (id, name, category, description, duration_min, price, image) VALUES (5, 'Preenchimento Labial', 'Injetáveis', 'Definição de contorno, hidratação profunda e volume sutil com ácido hialurônico de alta tecnologia e biocompatibilidade.', 60, 1350, '/assets/img/svc-labial.svg');
INSERT INTO services (id, name, category, description, duration_min, price, image) VALUES (6, 'Drenagem Linfática', 'Corporal', 'Massagem com manobras suaves e ritmadas que reduz a retenção hídrica, melhora a circulação e promove bem-estar imediato.', 60, 160, '/assets/img/svc-drenagem.svg');
INSERT INTO services (id, name, category, description, duration_min, price, image) VALUES (7, 'Massagem Modeladora', 'Corporal', 'Manobras intensas e localizadas para remodelar o contorno corporal, ativar o metabolismo local e melhorar a firmeza da pele.', 60, 175, '/assets/img/svc-massagem.svg');
INSERT INTO services (id, name, category, description, duration_min, price, image) VALUES (8, 'Depilação a Laser', 'Laser', 'Tecnologia de ponteira resfriada para redução progressiva e duradoura dos pelos com máximo conforto para todos os fototipos.', 30, 240, '/assets/img/svc-laser.svg');
INSERT INTO professionals (id, name, role, bio, photo) VALUES (1, 'Dra. Helena Duarte', 'Biomédica Esteta', 'Especialista em harmonização orofacial e procedimentos injetáveis minimamente invasivos, com foco em resultados elegantes e naturais.', '/assets/img/prof-helena.svg');
INSERT INTO professionals (id, name, role, bio, photo) VALUES (2, 'Dra. Camila Rocha', 'Dermatologista', 'Médica dermatologista dedicada ao rejuvenescimento global, protocolos clínicos avançados e tecnologias a laser.', '/assets/img/prof-camila.svg');
INSERT INTO professionals (id, name, role, bio, photo) VALUES (3, 'Juliana Prado', 'Esteticista', 'Especialista em cosmetologia avançada e tratamentos faciais e corporais de alto desempenho para saúde e vitalidade da pele.', '/assets/img/prof-juliana.svg');
INSERT INTO professionals (id, name, role, bio, photo) VALUES (4, 'Marina Alves', 'Fisioterapeuta Dermatofuncional', 'Fisioterapeuta referência em reabilitação estética, drenagem linfática especializada, remodelagem corporal e laserterapia.', '/assets/img/prof-marina.svg');
