-- Lumière Estética: schema + dados iniciais (D1)
CREATE TABLE IF NOT EXISTS services (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, duration_min INTEGER NOT NULL, price REAL NOT NULL, image TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS professionals (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, role TEXT NOT NULL, bio TEXT NOT NULL, photo TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS professional_services (professional_id INTEGER NOT NULL REFERENCES professionals(id) ON DELETE CASCADE, service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE, PRIMARY KEY (professional_id, service_id));
CREATE TABLE IF NOT EXISTS appointments (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, service_id INTEGER NOT NULL REFERENCES services(id), professional_id INTEGER NOT NULL REFERENCES professionals(id), date TEXT NOT NULL, time TEXT NOT NULL, start_min INTEGER NOT NULL, duration_min INTEGER NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL, notes TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'confirmado', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_appointments_prof_date ON appointments(professional_id, date);
CREATE INDEX IF NOT EXISTS idx_appointments_email ON appointments(email);
CREATE TABLE IF NOT EXISTS contacts (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT DEFAULT '', message TEXT NOT NULL, created_at TEXT NOT NULL);
